// YCloud webhook parser (adapted from Rasoi's production parser).
// Output fields are identical to the old Meta parser so every downstream node keeps working.
// Phones are stored WITHOUT '+' (e.g. 9198xxxxxxxx) to match the database convention.
var event = $input.first().json.body || $input.first().json;
var type = String(event.type || '');
var digits = function (p) { return String(p || '').replace(/[^0-9]/g, ''); };

// Delivery/read receipts for messages WE sent.
if (type === 'whatsapp.message.updated') {
  var wm = event.whatsappMessage || {};
  return [{ json: { is_status: true, has_message: false,
                    status_id: wm.id || '', wamid: wm.wamid || '',
                    status: wm.status || '', recipient: digits(wm.to),
                    error_code: (wm.errorCode || ''), error_message: (wm.errorMessage || '') } }];
}

var msg = event.whatsappInboundMessage || (event.data || {}).whatsappInboundMessage || event.message || null;
if (type !== 'whatsapp.inbound_message.received' || !msg || !msg.id) {
  return [{ json: { is_status: false, has_message: false } }];
}

var mtype = String(msg.type || 'text');
var text = '';
if (mtype === 'text') { text = (msg.text || {}).body || ''; }
else if (mtype === 'interactive') {
  var ia = msg.interactive || {};
  text = ((ia.button_reply || {}).id) || ((ia.list_reply || {}).id) ||
         ((ia.button_reply || {}).title) || ((ia.list_reply || {}).title) || '';
} else if (mtype === 'button') { text = (msg.button || {}).payload || (msg.button || {}).text || ''; }
else if (mtype === 'image') { text = (msg.image || {}).caption || ''; }

// Voice notes: YCloud gives a direct link (needs the YCloud API key header to download).
var audio = msg.audio || msg.voice || {};
var audioLink = audio.link || (audio.id ? ('https://api.ycloud.com/v2/whatsapp/media/' + audio.id) : '');
if (mtype === 'voice') { mtype = 'audio'; }

return [{ json: {
  is_status: false, has_message: true,
  message_id: msg.id, wamid: msg.wamid || '',
  customer_phone: digits(msg.from),
  customer_name: (msg.customerProfile || {}).name || '',
  msg_type: mtype,
  text: text, audio_id: audio.id || '', audio_link: audioLink,
  context_id: ((msg.context || {}).id) || ''
} }];

var base = $('Extract Message ID').first().json;
var dedupeCode = 0;
try { dedupeCode = $('Dedupe & Save Inbound').first().json.statusCode || 0; } catch (e) { dedupeCode = 0; }
var text = base.text || '';
if (base.msg_type === 'audio') {
  try { text = $('Whisper').first().json.text || ''; } catch (e) { text = ''; }
}
text = String(text).trim();

// A voice note that produced no transcript must NOT be sent to the AI as an
// empty string - the customer would get a nonsense reply. Flag it instead.
var transcriptionFailed = (base.msg_type === 'audio' && text === '');

// Buttons carry the order they belong to, e.g. "btn_cancel:FK-1042".
var ref = '';
var mm = text.match(/^(?:btn_[a-z]+|cr_[a-z]+|fk_pts_[a-z]+):((?:FK-)?\d+)$/i);
if (mm) { ref = (mm[1].toUpperCase().startsWith('FK-') ? mm[1].toUpperCase() : 'FK-' + mm[1]); }

// Always sanitize customer phone so it never has leading + or double country code
var rawPhone = String(base.customer_phone || '').replace(/\D/g, '');
if (rawPhone.length === 10) rawPhone = '91' + rawPhone;
if (rawPhone.length === 11 && rawPhone.startsWith('0')) rawPhone = '91' + rawPhone.slice(1);

return [{ json: {
  customer_phone: rawPhone,
  customer_name: base.customer_name,
  message_id: base.message_id,
  msg_type: base.msg_type,
  text: text,
  ref_order: ref,
  context_id: base.context_id || '',
  transcription_failed: transcriptionFailed,
  dedupe_status: dedupeCode
} }];

var d = $input.first().json;
var msg = 'Sorry, I could not make out that voice note.\n\n' +
  'Could you type your order instead? Or send the voice note again somewhere quieter.';
return [{ json: { customer_phone: d.customer_phone,
  outgoing: { type: 'text', text: { body: msg } } } }];

// Single decision point. Greetings, table scans and button taps never reach the
// AI, which is what makes them instant - no model call, no menu in the prompt.
var inp = $('Extract Input').first().json;
var ctx = $input.first().json || {};
if (Array.isArray(ctx)) { ctx = ctx[0] || {}; }

var S = ctx.settings || {};
var session = ctx.session || null;
var open = ctx.open_order || null;
var text = String(inp.text || '').trim();
var low = text.toLowerCase();

// phone verification from the website checkout: "VERIFY ABC123" (works even when staff handle the chat)
var vm = low.match(/^verify\s+([a-z0-9]{6})$/);
if (vm) {
  return [{ json: { route: 'verify', customer_phone: inp.customer_phone, verify_code: vm[1].toUpperCase() } }];
}

// Payment buttons work while staff handle the conversation and outside opening hours.
var riderPayment = low.match(/^fk_paid:([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/);
if ((inp.msg_type === 'button' || inp.msg_type === 'interactive') && (riderPayment || low === 'payment collected')) {
  return [{ json: { route: 'rider_payment', customer_phone: inp.customer_phone,
    context_id: inp.context_id || '', payment_order_id: riderPayment ? riderPayment[1] : null } }];
}

// Bare payment acknowledgements stay silent.
if (low === 'payment collected') {
  return [{ json: { route: 'ignore', customer_phone: inp.customer_phone } }];
}

// LOOP GUARD: if inbound message has NO text and is not a button/audio/media/location, stop immediately.
if (!text && inp.msg_type !== 'button' && inp.msg_type !== 'interactive' && inp.msg_type !== 'audio' && inp.msg_type !== 'image' && inp.msg_type !== 'location') {
  return [{ json: { route: 'ignore', customer_phone: inp.customer_phone } }];
}

// staff has taken over
if (session && session.ai_enabled === false) {
  return [{ json: { route: 'staff', customer_phone: inp.customer_phone } }];
}

// Find the last outbound bot message from chat history
var lastOutbound = '';
if (Array.isArray(ctx.history)) {
  for (var hi = ctx.history.length - 1; hi >= 0; hi--) {
    var hm = ctx.history[hi];
    if (hm && hm.direction === 'outbound') {
      lastOutbound = String(hm.content || '');
      break;
    }
  }
}
var isAfterCartSummary = lastOutbound.indexOf('confirm your order') !== -1;
var isAfterModeAsk = lastOutbound.indexOf('How would you like to get your order') !== -1;
var isAfterAddressAsk = lastOutbound.indexOf('full delivery address') !== -1;
var isAfterPointsAsk = (lastOutbound.indexOf('reward points') !== -1 && lastOutbound.indexOf('save ₹') !== -1);

// CHECKOUT ACTIONS:
// 1. Confirm: button btn_confirm:FK-x or typed (confirm/confirm order/place order/yes/ok) ONLY when draft is open AND last outbound was cart summary
var btnConfirmMatch = low.match(/^btn_confirm:((?:fk-)?\d+)$/i);
var isTypedConfirm = /^(confirm|confirm order|place order|yes|ok)$/i.test(low);
if (btnConfirmMatch || (isTypedConfirm && open && open.status === 'draft' && isAfterCartSummary)) {
  var cNum = btnConfirmMatch ? btnConfirmMatch[1].toUpperCase() : open.order_number;
  if (!cNum.startsWith('FK-')) cNum = 'FK-' + cNum;
  return [{ json: Object.assign({}, ctx, {
    route: 'checkout',
    checkout_action: 'confirm',
    customer_phone: inp.customer_phone,
    order_number: cNum
  }) }];
}

// 2. Use points: button fk_pts_yes:FK-x or typed "use points" ONLY right after points question
var ptsYesMatch = low.match(/^fk_pts_yes:((?:fk-)?\d+)$/i);
var isTypedUsePoints = /^(use points|use my points)$/i.test(low);
if (ptsYesMatch || (isTypedUsePoints && open && open.status === 'draft' && isAfterPointsAsk)) {
  var pyNum = ptsYesMatch ? ptsYesMatch[1].toUpperCase() : open.order_number;
  if (!pyNum.startsWith('FK-')) pyNum = 'FK-' + pyNum;
  return [{ json: Object.assign({}, ctx, {
    route: 'checkout',
    checkout_action: 'use_points',
    customer_phone: inp.customer_phone,
    order_number: pyNum
  }) }];
}

// 3. Skip points: button fk_pts_no:FK-x or typed "not now" / "no" right after points question
var ptsNoMatch = low.match(/^fk_pts_no:((?:fk-)?\d+)$/i);
var isTypedSkipPoints = /^(not now|skip points|no points|no)$/i.test(low);
if (ptsNoMatch || (isTypedSkipPoints && open && open.status === 'draft' && isAfterPointsAsk)) {
  var pnNum = ptsNoMatch ? ptsNoMatch[1].toUpperCase() : open.order_number;
  if (!pnNum.startsWith('FK-')) pnNum = 'FK-' + pnNum;
  return [{ json: Object.assign({}, ctx, {
    route: 'checkout',
    checkout_action: 'skip_points',
    customer_phone: inp.customer_phone,
    order_number: pnNum
  }) }];
}

// 4. Place order (final summary button)
var btnPlaceMatch = low.match(/^btn_place:((?:fk-)?\d+)$/i);
if (btnPlaceMatch) {
  var plNum = btnPlaceMatch[1].toUpperCase();
  if (!plNum.startsWith('FK-')) plNum = 'FK-' + plNum;
  return [{ json: Object.assign({}, ctx, {
    route: 'checkout',
    checkout_action: 'place',
    customer_phone: inp.customer_phone,
    order_number: plNum
  }) }];
}

// 5. Staged amend buttons on placed orders
var amendConfMatch = low.match(/^btn_amend_confirm:((?:fk-)?\d+)$/i);
if (amendConfMatch) {
  var acNum = amendConfMatch[1].toUpperCase();
  if (!acNum.startsWith('FK-')) acNum = 'FK-' + acNum;
  return [{ json: Object.assign({}, ctx, {
    route: 'button',
    button: 'amend_confirm',
    customer_phone: inp.customer_phone,
    order_number: acNum
  }) }];
}
var amendDiscMatch = low.match(/^btn_amend_discard:((?:fk-)?\d+)$/i);
if (amendDiscMatch) {
  var adNum = amendDiscMatch[1].toUpperCase();
  if (!adNum.startsWith('FK-')) adNum = 'FK-' + adNum;
  return [{ json: Object.assign({}, ctx, {
    route: 'button',
    button: 'amend_discard',
    customer_phone: inp.customer_phone,
    order_number: adNum
  }) }];
}

// Other button taps: modify, cancel
var btn = '';
var cancelReason = '';
var btnMatch = low.match(/^btn_(modify|cancel)\b/);
if (btnMatch) {
  btn = btnMatch[1] === 'cancel' ? 'cancel_ask' : btnMatch[1];
} else if (low === 'modify order' || low === 'modify')  { btn = 'modify'; }
else if (low === 'cancel order'  || low === 'cancel') { btn = 'cancel_ask'; }
else {
  var crMatch = low.match(/^cr_(wrong|wrongx|mind|mistake|slow|other|keep)\b/);
  if (crMatch) {
    var REASONS = { wrongx: 'wrong_items', mind: 'changed_mind', mistake: 'ordered_by_mistake', slow: 'taking_too_long', other: 'other' };
    if (crMatch[1] === 'wrong') { btn = 'wrong'; }
    else if (crMatch[1] === 'keep') { btn = 'keep'; }
    else { btn = 'cancel_do'; cancelReason = REASONS[crMatch[1]]; }
  }
}

// opening hours
var ist = new Date(Date.now() + (5.5 * 60 * 60 * 1000));
var hrs = ist.getUTCHours() + (ist.getUTCMinutes() / 60);
function toHrs(t) { var m = String(t || '').match(/^(\d{1,2}):(\d{2})/); return m ? Number(m[1]) + Number(m[2]) / 60 : null; }
var openH = toHrs(S.opens_at);
var closeH = toHrs(S.closes_at);
var isOpen = (openH === null || closeH === null || openH === closeH) ? true
  : (openH < closeH ? (hrs >= openH && hrs < closeH) : (hrs >= openH || hrs < closeH));

var base = {
  customer_phone: inp.customer_phone,
  customer_name: (ctx.customer && ctx.customer.name) || inp.customer_name || '',
  text: text, msg_type: inp.msg_type, is_open: isOpen,
  open_order: open, settings: S, menu: ctx.menu || '',
  pincodes: ctx.pincodes || [], promos: ctx.promos || [],
  history: ctx.history || [], customer: ctx.customer || null, active_order: ctx.active_order || null,
  menu_url: S.menu_url || 'https://friedking.vercel.app/?s=1'
};

// ---- A placed order cannot be cancelled on WhatsApp: tell the customer to call.
var placedOrder = (open && open.status !== 'draft') ? open : ((!open && ctx.active_order) ? ctx.active_order : null);
var NEG_CANCEL = /\b(don'?t|do not|dont|not|never|no)\s+(want\s+to\s+)?cancel/;
var textCancel = text.length > 0 && text.length <= 80 && /\bcancel/.test(low) && !NEG_CANCEL.test(low) && !/^(btn_|fk_|cr_keep)/.test(low);
var buttonCancel = /^btn_cancel\b/.test(low) || /^cr_(wrong|wrongx|mind|mistake|slow|other)\b/.test(low);
if (placedOrder && (textCancel || buttonCancel)) {
  return [{ json: Object.assign({}, base, { route: 'cancel_blocked', order_number: placedOrder.order_number }) }];
}
// nothing to cancel at all: do not show the cancel-reason list for an empty order number
if (!open && !ctx.active_order && (textCancel || buttonCancel)) {
  return [{ json: Object.assign({}, base, { route: 'button', button: 'no_order', order_number: '' }) }];
}

// ---- Delivery or takeaway, and the typed delivery address, for the customer's open draft.
if (open && open.status === 'draft') {
  var oType = String(open.order_type || '').toLowerCase();
  var oAddr = String(open.address || '').trim();
  var hasAddr = oAddr !== '' && oAddr.indexOf('Address to be confirmed') !== 0;
  var modeBtn = low.match(/^btn_mode:(delivery|pickup):((?:fk-)?\d+)$/);
  var modeWord = low.match(/^(?:(?:make it|change (?:it )?to|i want|i need|i'?ll take|please|pls|switch to)\s+)?(?:a |the )?(home delivery|delivery|deliver|take ?away|pick ?up|parcel)(?:\s+(?:please|pls))?[\s.!]*$/);
  var changeAddr = /^(?:change|new|edit|update|wrong)(?: my| the)?(?: delivery)? address[\s.!]*$/.test(low);
  var wantMode = '';
  var wantAddr = '';
  if (modeBtn) { wantMode = modeBtn[1]; }
  else if (modeWord && (inp.msg_type === 'text' || inp.msg_type === 'audio')) { wantMode = /deliver/.test(modeWord[1]) ? 'delivery' : 'pickup'; }
  else if (changeAddr) { wantMode = 'delivery'; }
  else if (oType === 'delivery' && !hasAddr && isAfterAddressAsk && text && (inp.msg_type === 'text' || inp.msg_type === 'audio') &&
           !/^(btn_|fk_|cr_)/.test(low) && !/^(add|remove|make|i want|i need|can i|what|how|do you|menu|hi|hii|hello|hey|thanks|thank you)\b/.test(low)) {
    wantMode = 'delivery';
    wantAddr = text;
  }
  if (wantMode) {
    // same mode again with an address already saved: just show the summary again (keep the address)
    if (wantMode === 'delivery' && !wantAddr && hasAddr && !changeAddr) { wantAddr = oAddr; }
    return [{ json: Object.assign({}, base, { route: 'setmode', order_number: open.order_number, mode: wantMode, address: wantAddr }) }];
  }
}

if (btn) {
  var extra = { route: 'button', button: btn, order_number: open ? open.order_number : '' };
  if (cancelReason) { extra.cancel_reason = cancelReason; }
  return [{ json: Object.assign({}, base, extra) }];
}

var TABLE = /^(?:hi|hii+|hey+|hello+)?[,.\s!]*(?:i\s*(?:'|')?\s*m|i\s*am|we\s*(?:'|')?\s*re|we\s*are)?\s*(?:sitting\s+)?(?:at\s+|on\s+)?table[\s#:-]*([a-z0-9]{1,4})[.!s]*$/;
var tm = (inp.msg_type !== 'audio') ? low.match(TABLE) : null;
if (tm) {
  return [{ json: Object.assign({}, base, { route: 'dinein', table_number: tm[1].toUpperCase() }) }];
}

if (inp.msg_type === 'reaction') {
  return [{ json: Object.assign({}, base, { route: 'ignore' }) }];
}

if (!isOpen) {
  var closedText = "We're closed right now - we're open " + (S.hours || 'soon') + '. ' +
    "I've saved your message; drop by again once we reopen, or browse the menu for next time.";
  return [{ json: Object.assign({}, base, {
    route: 'closed', canned_text: closedText,
    canned_cta: { label: 'Browse Menu', url: base.menu_url + (base.menu_url.indexOf('?') > -1 ? '&ph=' : '?ph=') + base.customer_phone }
  }) }];
}

var GREET = /^(hi|hii+|hey+|hello+|helo|yo|good\s*(morning|afternoon|evening)|start|menu|hi there)[\s!.,?]*$/;
if (inp.msg_type !== 'audio' && GREET.test(low)) {
  return [{ json: Object.assign({}, base, { route: 'greeting' }) }];
}

var ATTACH = ['image', 'video', 'document', 'sticker', 'contacts'];
if (ATTACH.indexOf(inp.msg_type) !== -1) {
  return [{ json: Object.assign({}, base, { route: 'attachment', attachment_type: inp.msg_type }) }];
}
if (inp.msg_type === 'location') {
  return [{ json: Object.assign({}, base, { route: 'attachment', attachment_type: 'location' }) }];
}

return [{ json: Object.assign({}, base, { route: 'ai' }) }];

function render(phone, text, buttons, cta) {
  if (cta && cta.url) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'cta_url', body: { text: String(text).slice(0, 1024) },
      action: { name: 'cta_url', parameters: {
        display_text: String(cta.label || 'Browse Menu').slice(0, 20), url: cta.url } } } } };
  }
  if (buttons && buttons.length > 0) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'button', body: { text: String(text).slice(0, 1024) },
      action: { buttons: buttons.slice(0, 3).map(function (b, i) {
        return { type: 'reply', reply: { id: b.id || ('btn_' + i), title: String(b.title || b).slice(0, 20) } };
      }) } } } };
  }
  return { customer_phone: phone, outgoing: { type: 'text', text: { body: String(text) } } };
}
function rs(n){ return 'Rs ' + Number(n||0).toLocaleString('en-IN'); }
function waPhone(p) {
  var d = String(p || '').replace(/\D/g, '');
  if (d.length === 10) return '91' + d;
  if (d.length === 11 && d.startsWith('0')) return '91' + d.slice(1);
  return d;
}

var d = {};
try { d = $('Route').first().json || {}; } catch (e) { d = $input.first().json || {}; }
var inp = {};
try { inp = $('Extract Input').first().json || {}; } catch (e) {}

var phone = waPhone(d.customer_phone || inp.customer_phone);
var name = d.customer_name ? (' ' + d.customer_name.split(' ')[0]) : '';
var back = (d.customer && Number(d.customer.total_orders) > 0) ? ' Welcome back!' : '';
var msg = 'Hello' + name + ', *Welcome to Fried King*' + (back ? back : ' 😊') + '\n\n' +
  'You can place your order here.\n\n' +
  'Tap the *Browse Menu* and select the items. 👇🏻';
var menuUrl = d.menu_url || (d.settings && d.settings.menu_url) || 'https://friedking.vercel.app/?s=1';
var ctaUrl = menuUrl + (menuUrl.indexOf('?') > -1 ? '&ph=' : '?ph=') + phone;

return [{ json: render(phone, msg, [], { label: 'Browse Menu', url: ctaUrl }) }];

function render(phone, text, buttons, cta) {
  if (cta && cta.url) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'cta_url', body: { text: String(text).slice(0, 1024) },
      action: { name: 'cta_url', parameters: {
        display_text: String(cta.label || 'Browse Menu').slice(0, 20), url: cta.url } } } } };
  }
  if (buttons && buttons.length > 0) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'button', body: { text: String(text).slice(0, 1024) },
      action: { buttons: buttons.slice(0, 3).map(function (b, i) {
        return { type: 'reply', reply: { id: String(b.id || ('btn_' + i)).slice(0, 256),
                                         title: String(b.title || b).slice(0, 20) } };
      }) } } } };
  }
  return { customer_phone: phone, outgoing: { type: 'text', text: { body: String(text) } } };
}
function rs(n) { return 'Rs ' + Number(n || 0).toLocaleString('en-IN'); }
function itemLines(o) {
  var list = (o && Array.isArray(o.items_json) && o.items_json.length) ? o.items_json : null;
  if (list) {
    return list.map(function (i) { return '- ' + i.name + ' x' + i.quantity; }).join('\n');
  }
  return String((o && o.items) || '').split(', ').filter(Boolean)
    .map(function (s) { return '- ' + s; }).join('\n');
}

var d = $input.first().json;
return [{ json: render(d.customer_phone, d.canned_text, [], d.canned_cta || null) }];

function render(phone, text, buttons, cta) {
  if (cta && cta.url) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'cta_url', body: { text: String(text).slice(0, 1024) },
      action: { name: 'cta_url', parameters: {
        display_text: String(cta.label || 'Browse Menu').slice(0, 20), url: cta.url } } } } };
  }
  if (buttons && buttons.length > 0) {
    return { customer_phone: phone, outgoing: { type: 'interactive', interactive: {
      type: 'button', body: { text: String(text).slice(0, 1024) },
      action: { buttons: buttons.slice(0, 3).map(function (b, i) {
        return { type: 'reply', reply: { id: String(b.id || ('btn_' + i)).slice(0, 256),
                                         title: String(b.title || b).slice(0, 20) } };
      }) } } } };
  }
  return { customer_phone: phone, outgoing: { type: 'text', text: { body: String(text) } } };
}
function rs(n) { return 'Rs ' + Number(n || 0).toLocaleString('en-IN'); }
function itemLines(o) {
  var list = (o && Array.isArray(o.items_json) && o.items_json.length) ? o.items_json : null;
  if (list) {
    return list.map(function (i) { return '- ' + i.name + ' x' + i.quantity; }).join('\n');
  }
  return String((o && o.items) || '').split(', ').filter(Boolean)
    .map(function (s) { return '- ' + s; }).join('\n');
}

// Handles every button that does not change the database:
// modify, cancel_ask (show reasons), keep, wrong (offer a fix), no_order
var d = $input.first().json;
var o = d.open_order || {};
var num = o.order_number || '';
var S = d.settings || {};
var phoneTxt = S.phone || '+91 97421 75222';
var menuCta = { label: 'Browse Menu', url: d.menu_url + (d.menu_url.indexOf('?') > -1 ? '&ph=' : '?ph=') + d.customer_phone };
var editable = ['draft', 'new', 'confirmed'].indexOf(o.status) !== -1;
var res;

if (d.button === 'modify') {
  if (!editable) {
    res = render(d.customer_phone,
      'Order ' + num + ' is already being prepared, so it can no longer be changed. ' +
      'For anything urgent please call ' + phoneTxt + '.\n\n' +
      'Want to add something? Just tell me and I will set it up as a separate order.', [], null);
  } else {
    res = render(d.customer_phone,
      'Sure - tell me what to change, for example "make it 2 biryanis", "remove the naan", "takeaway instead" or "change address". ' +
      'You can type it or send a voice note.\n\n' +
      'Order ' + num + ' right now:\n' + itemLines(o) + '\nTotal: ' + rs(o.total), [], null);
  }
} else if (d.button === 'cancel_ask') {
  res = { customer_phone: d.customer_phone, outgoing: { type: 'interactive', interactive: {
    type: 'list',
    body: { text: 'Before I cancel order ' + num + ', could you tell us why? It helps us improve.' },
    action: { button: 'Choose a reason', sections: [{ title: 'Reason', rows: [
